# ---------------------------------------------------------------------------
# City markers. GENERATED: each is the population-weighted centroid of the
# tracts inside that metro's PUMAs, from the 2020 centers-of-population
# file, not a coordinate typed from memory.
# `metro_key` is the key looked up in the scenario JSON's
# "by_metro" object; if that key is absent the marker renders in an explicit
# "no metro estimate available" state rather than showing anything invented.
# ---------------------------------------------------------------------------
CITIES: List[Dict[str, object]] = [
    {"metro_key": "atlanta", "label": "Atlanta", "lon": -84.33, "lat": 33.82},   # 1,491 tracts
    {"metro_key": "detroit", "label": "Detroit", "lon": -83.21, "lat": 42.51},   # 1,374 tracts
    {"metro_key": "houston", "label": "Houston", "lon": -95.43, "lat": 29.79},   # 1,587 tracts
    {"metro_key": "new_york", "label": "New York", "lon": -73.95, "lat": 40.73},   # 4,937 tracts
    {"metro_key": "phoenix", "label": "Phoenix", "lon": -112.01, "lat": 33.46},   # 1,102 tracts
    {"metro_key": "san_francisco", "label": "San Francisco", "lon": -122.21, "lat": 37.77},   # 1,102 tracts
]

# Standard-parallel-ish correction so the map is not stretched east-west.
REF_LAT = 39.0
# Degrees of longitude/latitude per isometric tile. Smaller = finer detail and
# more SVG nodes. At 0.7 the coastline was too coarse to read as the United
# States even once the outline itself was real; 0.42 roughly doubles the
# resolution in each direction and still renders smoothly.
TILE_DEG = 0.42


def plane(lon: float, lat: float) -> Tuple[float, float]:
    """Equirectangular projection with a cosine correction at REF_LAT."""
    return lon * math.cos(math.radians(REF_LAT)), lat


def map_config() -> Dict[str, object]:
    """Everything the frontend needs to draw and place things on the map."""
    pts = [plane(lon, lat) for lon, lat in US_OUTLINE]
    xs = [p[0] for p in pts]
    ys = [p[1] for p in pts]
    return {
        "outline": [list(p) for p in pts],
        "bounds": {"x0": min(xs), "x1": max(xs), "y0": min(ys), "y1": max(ys)},
        "tile": TILE_DEG * math.cos(math.radians(REF_LAT)),
        "tile_y": TILE_DEG,
        "cities": [
            {
                "metro_key": c["metro_key"],
                "label": c["label"],
                "x": plane(float(c["lon"]), float(c["lat"]))[0],
                "y": plane(float(c["lon"]), float(c["lat"]))[1],
            }
            for c in CITIES
        ],
    }
